-- ============================================================
-- 基线包含：电商核心功能（购物车/评论/收藏/浏览历史/商家端）
-- ============================================================

-- ---------- product 扩展字段 ----------
ALTER TABLE product
  ADD COLUMN origin VARCHAR(64) NULL COMMENT '产地' AFTER specs,
  ADD COLUMN ship_from VARCHAR(64) NULL COMMENT '发货地' AFTER origin,
  ADD COLUMN production_date VARCHAR(32) NULL COMMENT '生产日期' AFTER ship_from,
  ADD COLUMN material VARCHAR(128) NULL COMMENT '材质' AFTER production_date,
  ADD COLUMN merchant_id BIGINT NULL COMMENT '商家ID(NULL=自营)' AFTER material,
  ADD COLUMN sales INT NOT NULL DEFAULT 0 COMMENT '销量' AFTER merchant_id;

-- ---------- 商家表 ----------
CREATE TABLE merchant (
  id           BIGINT       NOT NULL AUTO_INCREMENT COMMENT '商家ID',
  user_id      BIGINT       NOT NULL COMMENT '关联用户',
  shop_name    VARCHAR(64)  NOT NULL COMMENT '店铺名称',
  shop_logo    VARCHAR(255) NULL COMMENT '店铺LOGO',
  description  VARCHAR(512) NULL COMMENT '店铺简介',
  address      VARCHAR(128) NULL COMMENT '经营地址',
  status       VARCHAR(16)  NOT NULL DEFAULT 'ACTIVE' COMMENT 'ACTIVE/DISABLED',
  created_at   DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at   DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  deleted      TINYINT      NOT NULL DEFAULT 0,
  PRIMARY KEY (id),
  UNIQUE KEY uk_user (user_id),
  KEY idx_status (status)
) ENGINE=InnoDB COMMENT='商家表';

-- ---------- 购物车 ----------
CREATE TABLE cart_item (
  id         BIGINT   NOT NULL AUTO_INCREMENT,
  user_id    BIGINT   NOT NULL,
  product_id BIGINT   NOT NULL,
  quantity   INT      NOT NULL DEFAULT 1,
  checked    TINYINT  NOT NULL DEFAULT 1 COMMENT '勾选状态',
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY uk_user_product (user_id, product_id),
  KEY idx_user (user_id)
) ENGINE=InnoDB COMMENT='购物车表';

-- ---------- 商品收藏 ----------
CREATE TABLE favorite (
  id         BIGINT   NOT NULL AUTO_INCREMENT,
  user_id    BIGINT   NOT NULL,
  product_id BIGINT   NOT NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY uk_user_product (user_id, product_id),
  KEY idx_user (user_id)
) ENGINE=InnoDB COMMENT='商品收藏表';

-- ---------- 浏览历史 ----------
CREATE TABLE browse_history (
  id         BIGINT   NOT NULL AUTO_INCREMENT,
  user_id    BIGINT   NOT NULL,
  product_id BIGINT   NOT NULL,
  viewed_at  DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY uk_user_product (user_id, product_id),
  KEY idx_user_time (user_id, viewed_at)
) ENGINE=InnoDB COMMENT='浏览历史表';

-- ---------- 商品评论 ----------
CREATE TABLE product_review (
  id             BIGINT       NOT NULL AUTO_INCREMENT,
  product_id     BIGINT       NOT NULL,
  user_id        BIGINT       NOT NULL,
  order_item_id  BIGINT       NULL COMMENT '关联订单明细(验证购买)',
  rating         TINYINT      NOT NULL DEFAULT 5 COMMENT '评分1~5',
  content        VARCHAR(1000) NOT NULL,
  spec_info      VARCHAR(255) NULL COMMENT '购买规格快照',
  merchant_reply VARCHAR(500) NULL COMMENT '商家回复',
  created_at     DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  deleted        TINYINT      NOT NULL DEFAULT 0,
  PRIMARY KEY (id),
  KEY idx_product (product_id, id),
  KEY idx_user (user_id)
) ENGINE=InnoDB COMMENT='商品评论表';

