UPDATE product SET image_url = CONCAT('https://picsum.photos/seed/aimall', id, '/600/600');

-- ---------- 产地/发货地/材质/生产日期/销量/商家 ----------
UPDATE product SET
  origin = CASE category
    WHEN 'PHONE' THEN '广东省东莞市'
    WHEN 'LAPTOP' THEN '江苏省苏州市'
    WHEN 'APPLIANCE' THEN '安徽省合肥市'
    WHEN 'CLOTHING' THEN '浙江省杭州市'
    WHEN 'BEAUTY' THEN '上海市'
    WHEN 'FOOD' THEN '山东省烟台市'
    WHEN 'MATERNAL' THEN '广东省汕头市'
    WHEN 'SPORTS' THEN '福建省泉州市'
    WHEN 'BOOK' THEN '北京市'
    WHEN 'HOME' THEN '广东省佛山市'
    WHEN 'JEWELRY' THEN '广东省深圳市水贝'
    WHEN 'BAGS' THEN '河北省保定市'
    WHEN 'SHOES' THEN '福建省晋江市'
    WHEN 'PET' THEN '上海市'
    WHEN 'HEALTH' THEN '江苏省泰州市'
    WHEN 'CAR' THEN '浙江省宁波市'
    ELSE '中国' END,
  ship_from = CASE category
    WHEN 'FOOD' THEN '山东省济南市'
    WHEN 'CLOTHING' THEN '浙江省杭州市'
    WHEN 'BOOK' THEN '北京市'
    WHEN 'JEWELRY' THEN '广东省深圳市'
    ELSE '广东省广州市' END,
  production_date = CASE
    WHEN category IN ('FOOD') THEN '2026-06-15'
    WHEN category IN ('BEAUTY','HEALTH') THEN '2026-03-01'
    ELSE '2026-01-10' END,
  material = CASE category
    WHEN 'CLOTHING' THEN '纯棉/涤纶混纺'
    WHEN 'JEWELRY' THEN '足金999/S925银'
    WHEN 'BAGS' THEN '尼龙/头层牛皮'
    WHEN 'SHOES' THEN '透气网面+橡胶大底'
    WHEN 'HOME' THEN '实木/环保板材'
    WHEN 'APPLIANCE' THEN 'ABS工程塑料/不锈钢'
    ELSE NULL END,
  sales = 50 + (id * 37) % 9800,
  merchant_id = CASE
    WHEN category IN ('PHONE','LAPTOP') THEN 1
    WHEN category = 'FOOD' THEN 2
    WHEN category = 'SPORTS' THEN 3
    ELSE NULL END;

